galZ(){return"\u062f\u0648\u06af\u0645\u06ce \xab\u0641\u0631\u06ce\u06a9\u0631\u0646\xbb \u0644 \u067e\u06d5\u0695\u06ce \u06a9\u06d5\u06cc\u0633\u06cc \u0628 \u0626\u06ce\u06a9 \u062f\u0627\u06af\u0631\u062a\u0646 \u06a9\u0627\u063a\u06d5\u0632\u0627 \u06a9\u06d5\u06cc\u0633\u06cc \u0628\u06c6 \u06a4\u0627\u0646 \u0686\u0627\u062a\u06ce\u0646 \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce \u062f\u0641\u0631\u06ce\u06a9\u06d5\u062a."},
galY(){return"\u0647\u06ce\u0634\u062a\u0627 \u0686 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc \u0646\u06cc\u0646\u0646."},
gLY(){return"\u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646\u0627 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06ce"},
galT(){return"\u0646\u0627\u06a4 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5: \u0686\u0627\u067e\u062e\u0627\u0646\u06d5)"},
galQ(){return"\u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u0646\u0627 \u0644\u06cc\u0646\u06a9\u06cc"},
galS(){return"\u06a4\u06cc \u0644\u06cc\u0646\u06a9\u06cc \u0628\u06c6 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06ce \u0628\u0641\u0631\u06ce\u06a9\u06d5. \u062f \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce \u062f\u0627 \u06a4\u06d5\u062f\u06a9\u06d5\u062a \u0648 \u0626\u06ce\u06a9 \u062c\u0627\u0631 Start \u062f\u0627\u062f\u06af\u0631\u06cc\u062a. \u062a\u0646\u06ce \u0626\u06ce\u06a9 \u062c\u0627\u0631 \u0648 \u062f \u0662\u0664 \u062f\u06d5\u0645\u0698\u0645\u06ce\u0631\u0627\u0646 \u062f\u0627 \u06a9\u0627\u0631 \u062f\u06a9\u06d5\u062a."},
galR(){return"\u06cc\u0627\u0646\u060c \u0628\u06c6 \u0647\u0646\u062f\u06ce \u0647\u06d5\u0645\u06cc \u0626\u06d5\u0648 \u06a9\u0627\u063a\u06d5\u0632\u06ce\u0646 \u062a\u0648 \u062f\u0641\u0631\u06ce\u06a9\u06d5\u06cc \u0628\u0628\u06cc\u0646\u06cc: \u06af\u0631\u0648\u0648\u067e\u06d5\u06a9\u0627 \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce \u062f\u06af\u06d5\u0644 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06ce \u0686\u06ce\u0628\u06a9\u06d5\u060c \u067e\u0627\u0634\u0627\u0646 \u06a4\u06cc \u0644\u06cc\u0646\u06a9\u06cc \u06a4\u06d5\u06a9\u06d5 \u0648 \u0648\u06cc \u06af\u0631\u0648\u0648\u067e\u06cc \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5. \u06a9\u0627\u063a\u06d5\u0632 \u062f\u06ce \u0628\u06c6 \u0647\u06d5\u0631\u062f\u0648\u0648\u06a9\u0627\u0646 \u062f \u06af\u0631\u0648\u0648\u067e\u06cc \u062f\u0627 \u06af\u06d5\u0647\u0646. \u062a\u0646\u06ce \u0626\u06ce\u06a9 \u0698 \u06a4\u0627\u0646 \u0647\u06d5\u0631\u062f\u0648\u0648 \u0644\u06cc\u0646\u06a9\u0627\u0646 \u0628\u06a9\u0627\u0631\u0628\u06cc\u0646\u06d5."},
alU(a,b){return a+" \xb7 \u0686\u0627\u06a4\u06d5\u0695\u06ce\u06cc Start (\u0644\u06cc\u0646\u06a9 \u0647\u06d5\u062a\u0627 "+b+" \u06a9\u0627\u0631 \u062f\u06a9\u06d5\u062a)"},
galV(){return"\u0644\u0627\u0628\u0631\u0646"},
galX(){return"\u0626\u06d5\u06a4 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06d5 \u0628\u0647\u06ce\u062a\u06d5 \u0644\u0627\u0628\u0631\u0646\u061f"},
alW(a){return"\xab"+a+"\xbb \u0686\u06cc\u062f\u06cc \u06a9\u0627\u063a\u06d5\u0632\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u0648\u06d5\u0631\u0646\u0627\u06af\u0631\u06cc\u062a. \u062a\u0648 \u062f\u0634\u06ce\u06cc \u0628 \u0644\u06cc\u0646\u06a9\u06d5\u06a9\u06ce \u0646\u0648\u0648 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0632\u06ce\u062f\u06d5 \u0628\u06a9\u06d5\u06cc."},
gPt(){return"\u0647\u06d5\u0646\u0627\u0631\u062f\u06d5\u06a9\u0631\u0646\u0627 \u062f\u0627\u062a\u0627\u06cc\u06ce\u0646 \u0645\u0646"},
gPu(){return"\u06a9\u06c6\u067e\u06cc\u06cc\u06d5\u06a9\u0627 \u062a\u06d5\u0645\u0627\u0645 \u06cc\u0627 \u062f\u0627\u062a\u0627\u06cc\u06ce\u0646 \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u0627 \u062a\u06d5 \u0644 \u0633\u06d5\u0631 \u0626\u0627\u0645\u06ce\u0631\u06ce \u062e\u06c6 \u2014 \u0628\u06c6 \u067e\u0627\u0631\u0627\u0633\u062a\u0646\u06ce \u0648 \u0628\u06c6 \u062e\u0648\u0627\u0646\u062f\u0646\u06ce \u0628\u06ce\u06cc \u0626\u06d5\u067e \u0648 \u0628\u06ce\u06cc \u0626\u06cc\u0646\u062a\u06d5\u0631\u0646\u06ce\u062a."},
ga6I(){return"\u062a\u0648 \u0641\u0627\u06cc\u0644\u06d5\u06a9\u06ce zip \u0648\u06d5\u0631\u062f\u06af\u0631\u06cc \u06a9\u0648 \u06a9\u06d5\u06cc\u0633\u060c \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u060c \u0642\u06d5\u0631\u0632\u060c \u062e\u06d5\u0631\u062c\u06cc\u060c \u0645\u0648\u0648\u0686\u06d5\u060c \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631 \u0648 \u067e\u062a\u0631 \u0648\u06d5\u06a9 \u062e\u0634\u062a\u06d5 \u062a\u06ce\u062f\u0627 \u0647\u06d5\u0646\u06d5 (\u0641\u0627\u06cc\u0644\u06ce\u0646 CSV \u06cc\u06ce\u0646 \u062f Excel \u062f\u0627 \u062f\u0647\u06ce\u0646\u06d5 \u06a4\u06d5\u06a9\u0631\u0646)\u060c \u0628 \u067e\u06d5\u0695\u06d5\u06a9\u06ce \u0628 \u0646\u0627\u06a4\u06ce index.html \u06a4\u06d5 \u06a9\u0648 \u062f \u0647\u06d5\u0631 \u0648\u06ce\u0628\u06af\u06d5\u0695\u06d5\u06a9\u06ce \u062f\u0627 \u062f\u0647\u06ce\u062a\u06d5 \u06a4\u06d5\u06a9\u0631\u0646 \u2014 \u0628 \u06af\u06d5\u0695\u0627\u0646\u060c \u0628\u06ce\u06cc \u0626\u06cc\u0646\u062a\u06d5\u0631\u0646\u06ce\u062a \u0648 \u0628\u06ce\u06cc \u0626\u06d5\u067e. zip \u06a4\u06d5\u06a9\u06d5 \u0648 \u062f\u0648\u0648 \u062c\u0627\u0631\u0627\u0646 \u06a9\u0644\u06cc\u06a9 \u0644 index.html \u0628\u06a9\u06d5."},
ga6x(){return"\u0648\u06ce\u0646\u06d5 \u0648 \u0641\u0627\u06cc\u0644\u0627\u0646 \u0698\u06cc \u062a\u06ce\u06a9\u06d5"},
a6y(a,b){return"\u0646\u06ce\u0632\u06cc\u06a9\u06cc "+a+" ("+b+" \u0641\u0627\u06cc\u0644). \u062f \u0686\u06d5\u0646\u062f \u067e\u0627\u0631\u0686\u06d5\u06cc\u06ce\u0646 zip \u062f\u0627 \u062f\u0647\u06ce\u062a\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646 \u2014 \u0647\u06d5\u0645\u06cc\u0627\u0646 \u062f \u0647\u06d5\u0645\u0627\u0646 \u0628\u0648\u062e\u0686\u06d5\u06cc\u06ce zip\u0640\u0627 \u062f\u0627\u062a\u0627\u06cc\u0627\u0646 \u062f\u0627 \u06a4\u06d5\u06a9\u06d5 \u062f\u0627 \u06a9\u0648 \u0644\u06cc\u0646\u06a9\u06ce\u0646 index.html \u06a9\u0627\u0631 \u0628\u06a9\u06d5\u0646."},
ga6z(){return"\u062f \u0686\u06d5\u0646\u062f \u067e\u0627\u0631\u0686\u06d5\u06cc\u06ce\u0646 zip \u062f\u0627 \u062f\u0647\u06ce\u062a\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646 \u2014 \u0647\u06d5\u0645\u06cc\u0627\u0646 \u062f \u0647\u06d5\u0645\u0627\u0646 \u0628\u0648\u062e\u0686\u06d5\u06cc\u06ce zip\u0640\u0627 \u062f\u0627\u062a\u0627\u06cc\u0627\u0646 \u062f\u0627 \u06a4\u06d5\u06a9\u06d5 \u062f\u0627 \u06a9\u0648 \u0644\u06cc\u0646\u06a9\u06ce\u0646 index.html \u06a9\u0627\u0631 \u0628\u06a9\u06d5\u0646."},
ga6a(){return"\u062f\u0627\u062a\u0627\u06cc\u06ce\u0646 \u0645\u0646 \u062f\u0627\u0628\u06d5\u0632\u06cc\u0646\u06d5"},
a6B(a){return"\u062e\u0648\u0627\u0646\u062f\u0646\u0627 "+a+"\u2026"},
gIL(){return"\u0686\u06ce\u06a9\u0631\u0646\u0627 zip\u2026"},
