a6d(a){return"\u0647\u0627\u062a\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646. "+a+" \u0641\u0627\u06cc\u0644 \u0646\u06d5\u0647\u0627\u062a\u0646\u06d5 \u062f\u0627\u0628\u06d5\u0632\u0627\u0646\u062f\u0646 \u0648 \u062f \u06a9\u06c6\u067e\u06cc\u06cc\u06ce \u062f\u0627 \u0646\u06cc\u0646\u0646."},
a6w(a){return"\u0647\u06d5\u0646\u0627\u0631\u062f\u06d5\u06a9\u0631\u0646 \u0633\u06d5\u0631\u0646\u06d5\u06a9\u06d5\u0641\u062a: "+a},
ga6b(){return"\u0647\u06d5\u0646\u0627\u0631\u062f\u06d5\u06a9\u0631\u0646 \u0647\u0627\u062a\u06d5 \u0647\u06d5\u06b5\u0648\u06d5\u0634\u0627\u0646\u062f\u0646."},
a6H(a){return a+" \u2014 \u06a9\u06c6\u067e\u06cc\u06cc\u0627 \u062f\u0627\u062a\u0627\u06cc\u0627\u0646"},
a6D(a){return"\u06a9\u06c6\u067e\u06cc\u06cc\u06d5\u06a9\u0627 \u062a\u0646\u06ce-\u062e\u0648\u0627\u0646\u062f\u0646\u06ce \u0644 "+a+" \u0647\u0627\u062a\u06cc\u06d5 \u0686\u06ce\u06a9\u0631\u0646. \u0628\u06ce\u06cc \u0626\u06d5\u067e \u0648 \u0628\u06ce\u06cc \u0626\u06cc\u0646\u062a\u06d5\u0631\u0646\u06ce\u062a \u06a9\u0627\u0631 \u062f\u06a9\u06d5\u062a."},
ga6E(){return"\u06af\u06d5\u0695\u0627\u0646\u2026"},
a6G(a,b){return"\u0646\u06cc\u0634\u0627\u0646\u062f\u0627\u0646\u0627 "+a+" \u0698 "+b},
ga6F(){return"\u067e\u062a\u0631 \u0646\u06cc\u0634\u0627\u0646 \u0628\u062f\u06d5"},
ga6C(){return"\u0686 \u062a\u0634\u062a \u0644 \u06a4\u06ce\u0631\u06ce \u0646\u06cc\u0646\u0646."},
ga6f(){return"\u06a9\u06d5\u06cc\u0633"},
ga6s(){return"\u0645\u06ce\u0698\u0648\u0648\u06cc\u0627 \u0642\u06c6\u0646\u0627\u063a\u0627\u0646"},
ga6m(){return"\u0646\u0627\u0645\u06d5"},
